import sys; sys.path.insert(0,'_exp')
from ins import ins, D
p='x3/lines.py'; s=open(p,encoding='utf-8').read(); assert 'C27b' not in s
blk=(
D('C27b','claude_point','加练大题：2017–2018 期中第 4 题，12 分。(a) 用消元法求 det A；(b) 用 det A 的值求 det B——B 是两个矩阵的和。','加练一道大题：二零一七到二零一八学年期中，第四题，十二分。第一问，用消元法求A的行列式；第二问，用这个值，求B的行列式，而B是两个矩阵相加。')+
D('C27c','claude_explain','A 的左上角是 0，先交换 R₁、R₂。换一次行，行列式变号——记下一个负号。','A的左上角是零，不能当主元。先交换第一、二行。换一次行，行列式变号，先记下一个负号。')+
D('C27d','claude_explain','R₃ + 2R₁ 得 (0, 0, 5, 5)；R₄ − R₁ 得 (0, 1, −3, −4)；再减 R₂ 得 (0, 0, −5, −7)；再加 R₃ 得 (0, 0, 0, −2)。','第三行加两倍第一行，得零、零、五、五；第四行减第一行，得零、一、负三、负四；再减第二行，得零、零、负五、负七；最后加第三行，得零、零、零、负二。')+
D('C27e','claude_explain','上三角了，对角线相乘：1 × 1 × 5 × (−2) = −10。再乘换行的负号：det A = 10。','上三角了，对角线相乘：一乘一乘五乘负二，等于负十。再乘上换行的那个负号，A的行列式等于十。')+
D('D06a','ds_proud','(b) 简单！两个矩阵都是 A 换了换行，各是 10，加起来 20！','第二问简单！两个矩阵都是A换了换行，行列式各是十，加起来二十！',mood='easy')+
D('C27f','claude_explain','陷阱！行列式没有加法：det(B₁ + B₂) ≠ det B₁ + det B₂。必须先把 B 加出来，再看它的每一行。','陷阱！行列式没有加法：两个矩阵相加的行列式，不等于行列式相加。必须先把B加出来，再看它的每一行。')+
D('C27g','claude_explain','把 A 的四行记作 r₁ … r₄。逐行对照，B 的四行是：2r₁、r₂ + r₃、r₂ + r₃ + r₄、2r₂ + r₄。','把A的四行记作r一到r四。逐行对照，B的四行分别是：二倍r一；r二加r三；r二加r三加r四；二倍r二加r四。')+
D('C27h','claude_explain','倍加不改行列式：第 3 行减第 2 行，剩 r₄；第 4 行减新的第 3 行，剩 2r₂；第 2 行减它的一半，剩 r₃。','倍加不改变行列式：第三行减第二行，剩下r四；第四行减新的第三行，剩下二倍r二；第二行减去它的一半，剩下r三。')+
D('C27i','claude_explain','现在 B 的行是 2r₁、r₃、r₄、2r₂。提出两个 2；顺序 r₁ r₃ r₄ r₂ 换两次行就复原，符号不变。det B = 4 × 10 = 40。','现在B的四行是：二倍r一、r三、r四、二倍r二。提出两个二；剩下的行顺序是r一、r三、r四、r二，换两次行就能复原，符号不变。所以B的行列式等于四乘十，等于四十。')+
D('G03b','gpt_cross','四十，不是二十。考场上这一问写 20 的，一分都拿不到。','四十，不是二十。考场上这一问写二十的，一分都拿不到。')+
D('C27j','claude_point','再来一道：2023–2024 期中第 7 题，12 分。求行列式并判断是否奇异：(i) [[2, 2, 1], [2, 3, 5], [2, 5, 3]]；(ii) A² − A − 2I = O。','再来一道：二零二三到二零二四学年期中，第七题，十二分。求行列式，并判断是否奇异。第一问是一个具体的三阶矩阵；第二问只告诉你，A方减A减二I等于零矩阵。')+
D('C27k','claude_explain','(i)：第一列全是 2。R₂ − R₁ 得 (0, 1, 4)，R₃ − R₁ 得 (0, 3, 2)，再减 3R₂ 得 (0, 0, −10)。det = 2 × 1 × (−10) = −20 ≠ 0，非奇异。','第一问：第一列全是二。第二行减第一行，得零、一、四；第三行减第一行，得零、三、二；再减三倍第二行，得零、零、负十。行列式等于二乘一乘负十，等于负二十，不为零，所以非奇异。')+
D('C27l','claude_explain','(ii)：这里行列式定不下来，但能判断。移项 A² − A = 2I，提出 A：A(A − I) = 2I，两边除以 2：A · ½(A − I) = I。','第二问：这里行列式定不下来，但能判断。移项，A方减A等于二I；提出A，A乘括号A减I，等于二I；两边除以二：A乘二分之一的A减I，等于单位矩阵。')+
D('C27m','claude_explain','找到了和 A 相乘得 I 的矩阵，A 就非奇异，A⁻¹ = ½(A − I)。套路：常数项移到一边，另一边提出 A。','找到了一个矩阵，和A相乘等于I，A就非奇异，而且A的逆等于二分之一的A减I。这类题的套路：把常数项移到一边，另一边提出A。')+
D('D06b','ds_happy','和第一章复习里 A 的三次方那道，是同一个套路！','和第一章复习里，A的三次方那一道，是同一个套路！',mood='easy')
)
ins(p,{'C27a':blk})
